"""Inspect the workspace: list files and summarize any SQLite databases."""

import os
import sqlite3

CWD = os.getcwd()

print("=== Files in current directory ===")
for entry in sorted(os.listdir(CWD)):
    path = os.path.join(CWD, entry)
    kind = "dir" if os.path.isdir(path) else "file"
    size = os.path.getsize(path) if os.path.isfile(path) else "-"
    print(f"{kind:4} {size:>10}  {entry}")

print("\n=== SQLite databases ===")
db_extensions = (".db", ".sqlite", ".sqlite3", ".db3")
found_db = False
for entry in sorted(os.listdir(CWD)):
    path = os.path.join(CWD, entry)
    if not os.path.isfile(path):
        continue
    if entry.lower().endswith(db_extensions):
        found_db = True
        print(f"\n--- Database: {entry} ---")
        try:
            with sqlite3.connect(path) as conn:
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("  (no tables)")
                for (table,) in tables:
                    print(f"\n  Table: {table}")
                    for row in cur.execute(f"PRAGMA table_info({table})"):
                        print(f"    column: {row[1]}  type={row[2]}  notnull={row[3]}  default={row[4]}  pk={row[5]}")
        except sqlite3.DatabaseError as exc:
            print(f"  could not open as SQLite: {exc}")
if not found_db:
    print("  (no .db/.sqlite/.sqlite3 files found)")

"""Inspect the workspace for SQLite databases and report their schema."""

import os
import sqlite3


def main() -> None:
    print("=== Workspace files ===")
    for entry in sorted(os.listdir(".")):
        print(entry)

    db_candidates = [
        name
        for name in os.listdir(".")
        if name.lower().endswith((".db", ".sqlite", ".sqlite3"))
        and os.path.isfile(name)
    ]

    if not db_candidates:
        print("\nNo SQLite database files found in the current folder.")
        return

    for db_name in db_candidates:
        print(f"\n=== Database: {db_name} ===")
        conn = sqlite3.connect(db_name)
        try:
            cur = conn.cursor()
            cur.execute(
                "SELECT name, sql FROM sqlite_master "
                "WHERE type IN ('table', 'index', 'view') ORDER BY name"
            )
            for name, ddl in cur.fetchall():
                print(f"-- {name} --")
                print(ddl or "(no DDL)")
        finally:
            conn.close()


if __name__ == "__main__":
    main()

"""Inspect the task workspace: list files and report any SQLite database schema.

This helper only reads local workspace metadata; it performs no writes,
no network access, and no unrelated operations.
"""

import os
import sqlite3

DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3", ".db3")


def main() -> None:
    print("=== Files in workspace ===")
    entries = sorted(os.listdir("."))
    for entry in entries:
        full = os.path.join(".", entry)
        if os.path.isfile(full):
            print(f"file: {entry}  ({os.path.getsize(full)} bytes)")
        else:
            print(f"dir:  {entry}/")

    dbs = [
        entry
        for entry in entries
        if os.path.isfile(entry) and entry.lower().endswith(DB_EXTENSIONS)
    ]
    if not dbs:
        print("\n=== No SQLite database files found in workspace root ===")
        return

    for db in dbs:
        print(f"\n=== SQLite database: {db} ===")
        try:
            with sqlite3.connect(db) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' "
                    "ORDER BY name"
                ).fetchall()
                print("Tables:", [row["name"] for row in tables])
                for row in tables:
                    table = row["name"]
                    print(f"\n--- schema of {table} ---")
                    for schema_row in cur.execute(
                        "SELECT sql FROM sqlite_master WHERE type='table' AND name=?",
                        (table,),
                    ):
                        print(schema_row["sql"])
                    print(f"--- columns of {table} ---")
                    for col in cur.execute(f'PRAGMA table_info("{table}")'):
                        print(
                            f"  {col['cid']}: {col['name']} "
                            f"({col['type']}, notnull={col['notnull']}, "
                            f"pk={col['pk']})"
                        )
                    try:
                        count = cur.execute(
                            f'SELECT COUNT(*) AS n FROM "{table}"'
                        ).fetchone()["n"]
                        print(f"--- row count of {table}: {count} ---")
                    except sqlite3.OperationalError as exc:
                        print(f"--- row count unavailable: {exc} ---")
        except sqlite3.DatabaseError as exc:
            print(f"Error reading {db}: {exc}")


if __name__ == "__main__":
    main()

